final class LuckPermsBridge implements PermissionBridge{private final Object luckPerms;private final Method getPlayerAdapter;private LuckPermsBridge(Object l,Method g){luckPerms=l;getPlayerAdapter=g;}static PermissionBridge create(){try{Class<?>p=Class.forName("net.luckperms.api.LuckPermsProvider");Object api=p.getMethod("get").invoke(null);Method adapter=api.getClass().getMethod("getPlayerAdapter",Class.class);return new LuckPermsBridge(api,adapter);}catch(ReflectiveOperationException e){return PermissionBridge.vanilla();}}@Override public boolean has(ServerCommandSource source,String node,int fallback){ServerPlayerEntity player=source.getPlayer();if(player==null)return source.hasPermissionLevel(fallback);try{Object adapter=getPlayerAdapter.invoke(luckPerms,ServerPlayerEntity.class);Class<?>pa=Class.forName("net.luckperms.api.platform.PlayerAdapter");Object data=pa.getMethod("getPermissionData",Object.class).invoke(adapter,player);Class<?>pd=Class.forName("net.luckperms.api.cacheddata.CachedPermissionData");Object tristate=pd.getMethod("checkPermission",String.class).invoke(data,node);String value=String.valueOf(tristate);if("TRUE".equalsIgnoreCase(value))return true;if("FALSE".equalsIgnoreCase(value))return false;}catch(ReflectiveOperationException ignored){}return source.hasPermissionLevel(fallback);}}
